function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function openSurvey(step=0){lastFocus=document.activeElement;draft=structuredClone(profile);surveyStep=step;renderSurvey();$('#survey').showModal();$('#survey-close').focus()}
function closeSurvey(save=false){if(save){const dietChanged=profile.diet!==draft.diet;profile=structuredClone(draft);put('profile',profile);if(dietChanged){category='All';$$('[data-category]').forEach(b=>b.classList.remove('active'))}applyProfile();toast(copy[profile.lang].continueHome)}try{sessionStorage.setItem('roombap-intro-seen','1')}catch{}$('#survey').close();draft=null;(lastFocus||$('#preferences')).focus()}
function choice(value,label,sub,icon,selected,group){return `<button type="button" class="choice ${selected?'selected':''}" data-group="${group}" data-value="${value}" aria-pressed="${selected}"><span class="choice-icon">${icon}</span><span><strong>${escapeHTML(label)}</strong>${sub?`<small>${escapeHTML(sub)}</small>`:''}</span><span class="tick">✓</span></button>`}
function renderSurvey(){const c=t();$('#step-label').textContent=`${String(surveyStep+1).padStart(2,'0')} / 04 · ${c.steps[surveyStep]}`;$('#survey-title').textContent=c.titles[surveyStep];$('#survey-description').textContent=c.descs[surveyStep];$('#survey-progress').innerHTML=[0,1,2,3].map(i=>`<span class="${i<=surveyStep?'current':''}"></span>`).join('');$('#survey-back').hidden=surveyStep===0;$('#survey-back').textContent=c.back;$('#survey-next').textContent=surveyStep===3?c.finish:c.next;$('#survey-skip').textContent=c.skip;$('#privacy-note').textContent=c.privacy;
 let body='';
 if(surveyStep===0){body=`<label class="field-label">${c.lang}</label><div class="language-options">${[['en','English','EN'],['ja','Japanese','JA'],['zh','Chinese','ZH']].map(x=>choice(x[0],x[1],'',x[2],draft.lang===x[0],'lang')).join('')}</div><label class="field-label" for="country">${c.country}</label><select id="country" class="survey-select"><option value="">${c.countryNone}</option>${['United States','Japan','Mainland China','Taiwan','Hong Kong','Singapore','Thailand','Vietnam','Indonesia','Malaysia','United Kingdom','Australia','South Korea','Other'].map(x=>`<option ${draft.country===x?'selected':''}>${x}</option>`).join('')}</select>`}
 if(surveyStep===1){body=`<div class="options-stack">${diets.map((x,i)=>choice(x,c.diet[i],c.dietSub[i],['🍽️','🥚','🥬','🐟','☾'][i],draft.diet===x,'diet')).join('')}</div><p class="field-label">${c.avoid}</p><div class="extra-prefs">${[['pork',c.pork,'🐷'],['beef',c.beef,'🐮']].map(x=>choice(x[0],x[1],'',x[2],draft.avoid.includes(x[0]),'avoid')).join('')}</div>`}
 if(surveyStep===2){body=`<div class="options-stack">${spices.map((x,i)=>choice(x,c.spice[i],c.spiceSub[i],['🌱','🌶️','🔥','✨'][i],draft.spice===x,'spice')).join('')}</div>`}
 if(surveyStep===3){const labelIndex={en:2,ko:3,ja:4,zh:5}[draft.lang];body=`<div class="allergy-grid">${allergens.map(x=>choice(x[0],x[labelIndex],'',x[1],draft.allergies.includes(x[0]),'allergy')).join('')}</div>${choice('none',c.allergyNone,'','✓',draft.allergies.length===0&&!draft.other,'allergy-none')}<input id="allergy-other" class="allergy-other" maxlength="160" aria-label="${escapeHTML(c.other)}" placeholder="${escapeHTML(c.other)}" value="${escapeHTML(draft.other)}"><p class="gentle-note">${c.allergyNote}</p>`}
 $('#survey-body').innerHTML=body;
 $('#country')?.addEventListener('change',e=>draft.country=e.target.value);
 $('#allergy-other')?.addEventListener('input',e=>{draft.other=e.target.value;$('#survey-body [data-group="allergy-none"]').classList.toggle('selected',!draft.other&&draft.allergies.length===0)});
 $$('[data-group]').forEach(b=>b.onclick=()=>{let {group,value}=b.dataset;if(group==='lang')draft.lang=value;if(group==='diet')draft.diet=value;if(group==='spice')draft.spice=value;if(group==='avoid'){draft.avoid=draft.avoid.includes(value)?draft.avoid.filter(x=>x!==value):[...draft.avoid,value]}if(group==='allergy'){draft.allergies=draft.allergies.includes(value)?draft.allergies.filter(x=>x!==value):[...draft.allergies,value]}if(group==='allergy-none'){draft.allergies=[];draft.other=''}renderSurvey();$('#survey-body [data-group="'+group+'"][data-value="'+value+'"]')?.focus()});
}
$('#survey-close').onclick=()=>closeSurvey();$('#survey-skip').onclick=()=>closeSurvey();$('#survey').addEventListener('cancel',e=>{e.preventDefault();closeSurvey()});$('#survey-back').onclick=()=>{surveyStep=Math.max(0,surveyStep-1);renderSurvey()};$('#survey-next').onclick=()=>{if(surveyStep<3){surveyStep++;renderSurvey();$('#survey').scrollTop=0;$('#survey-next').focus()}else closeSurvey(true)};
$('#preferences').onclick=()=>openSurvey(1);$('#language').onclick=()=>openSurvey(0);
function applyProfile(){$('#language').textContent=profile.lang.toUpperCase()+' ▾';document.documentElement.lang=profile.lang;const labels=[];const c=copy[profile.lang];if(profile.diet!=='any')labels.push(c.diet[diets.indexOf(profile.diet)]);if(profile.spice!=='any')labels.push(c.spice[spices.indexOf(profile.spice)]);profile.avoid.forEach(x=>labels.push(x==='pork'?c.pork:c.beef));if(profile.allergies.length||profile.other)labels.push(profile.lang==='ko'?'알레르기 확인 필요':'Ingredient review needed');$('#profile-summary').hidden=!labels.length;$('#profile-summary').innerHTML=labels.map(x=>`<span>${escapeHTML(x)}</span>`).join('')+`<button id="edit-summary">${c.edit}</button>`;$('#edit-summary')?.addEventListener('click',()=>openSurvey(1));renderFoods();}
function bindCards(parent){bindRestaurantCards(parent)}
const placeCategoryInfo={Rice:{icon:'🍚',photo:'rice',label:'밥·덮밥'},Chicken:{icon:'🍗',photo:'chicken',label:'치킨'},Noodles:{icon:'🍜',photo:'noodles',label:'면 요리'},Chinese:{icon:'🥟',photo:'dumplings',label:'중식·만두·딤섬'},Sushi:{icon:'🍣',label:'초밥'},Soup:{icon:'🥘',photo:'noodles',label:'국밥·탕'},'Street food':{icon:'🍢',label:'분식'},BBQ:{icon:'🥩',label:'고기·구이'},Dessert:{icon:'🍨',label:'디저트'},Halal:{icon:'🕌',label:'할랄'},Salad:{icon:'🥗',label:'샐러드'}};
function restaurantName(p){return p.en}
function restaurantCard(p){const title=escapeHTML(p.en);return `<article class="food-card place-card"><button class="place-visual" data-place="${p.id}" aria-label="View ${title}">${window.RoomBapMedia.photo(p,'catalog-photo')}</button><button class="save-button ${saved.includes(p.id)?'saved':''}" data-place-save="${p.id}" aria-label="Save ${title}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><button class="card-main" data-place="${p.id}"><h3>${title}</h3><p class="place-ko">${escapeHTML(p.category)} · ${escapeHTML(p.areaEn||'Hongdae')}</p><p class="description">${escapeHTML(p.kind)}</p><div class="price-row"><strong>${p.priceRange?escapeHTML(p.priceRange):'See map for prices'}</strong></div><p class="place-price-label">${escapeHTML(p.priceLabel||'Google Maps price range')}</p>${p.dietaryNote?`<p class="place-diet-note">${escapeHTML(p.dietaryNote)}</p>`:''}<div class="place-map-cta"><span>${escapeHTML(window.RoomBapMedia.label(p.id))}</span><b>Details ↗</b></div></button></article>`}
function bindRestaurantCards(parent){parent.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>openRestaurant(b.dataset.place));parent.querySelectorAll('[data-place-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.placeSave;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];put('saved',saved);b.classList.toggle('saved',saved.includes(id));b.textContent=saved.includes(id)?'♥':'♡';b.setAttribute('aria-pressed',saved.includes(id));toast(saved.includes(id)?'Restaurant saved.':'Restaurant removed from saved.')})}
function detailFlow(bodyHtml,stickyHtml){$('#detail').classList.add('order-flow');detail(bodyHtml);$('#detail-sticky').innerHTML=stickyHtml||''}
function menuRow(item){const soldOut=item.soldOut;const icon=placeCategoryInfo[item.category]?.icon||'🍽️';const tag=soldOut?'div':'button';const attrs=soldOut?'':`type="button" data-menu-item="${item.id}"`;return `<${tag} class="menu-row${soldOut?' sold-out':''}" ${attrs}><span class="menu-row-info"><span class="menu-row-name">${escapeHTML(item.name)}</span><span class="menu-row-desc">${escapeHTML(item.description)}</span><span class="menu-row-price">₩${item.price.toLocaleString()}</span>${soldOut?'<span class="menu-row-soldout-label">Sold out</span>':''}</span><span class="menu-row-photo-wrap"><span class="menu-row-photo menu-visual" data-cat="${escapeHTML(item.category)}" aria-hidden="true">${icon}</span><span class="menu-row-add" aria-hidden="true">${soldOut?'–':'+'}</span></span></${tag}>`}
function venueResearchHTML(p){if(!p.dietaryNote)return '';return `<div class="venue-research-note"><strong>${escapeHTML(p.dietaryNote)}</strong><p>${escapeHTML(p.addressEn)}</p><p>${escapeHTML(p.deliveryNote)}</p><a href="${escapeHTML(p.source)}" target="_blank" rel="noopener noreferrer">View source listing ↗</a> · <a href="${escapeHTML(p.mapUrl)}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a>${p.dietarySource?` · <a href="${escapeHTML(p.dietarySource)}" target="_blank" rel="noopener noreferrer">Dietary listing ↗</a>`:''}<small>Checked 29 Oct 2026 · No confirmed RoomBap partnership</small></div>`}
function renderRestaurantMenu(p,menu,activeCat){const cats=[...new Set(menu.items.map(i=>i.category))];const list=menu.items.filter(i=>i.category===activeCat);const inCart=cart.restaurantId===p.id&&cart.items.length;const t=inCart?cartTotals():null;const body=`${window.RoomBapMedia.photo(p,'venue-detail-photo')}<p class="detail-kicker">${escapeHTML(p.category)} · ${escapeHTML(p.kind)}</p><h2 class="detail-title" id="detail-title">${escapeHTML(p.en)}</h2>${window.RoomBapMedia.credit(p.id)}${venueResearchHTML(p)}<span class="demo-badge">${menu.referenceSource?'Listed menu references · demo checkout':'Demo menu · prices and options are illustrative'}</span><p class="order-fee-line">Delivery ₩${menu.deliveryFee.toLocaleString()} (demo) · Min. order ₩${menu.minOrder.toLocaleString()} (demo)</p><div class="menu-tabs" role="tablist">${cats.map(c=>`<button data-menu-cat="${escapeHTML(c)}" class="${c===activeCat?'active':''}" aria-pressed="${c===activeCat}">${escapeHTML(c)}</button>`).join('')}</div>${list.map(menuRow).join('')}<button class="text-button full-button" id="place-save-detail">${saved.includes(p.id)?'♥ Saved · tap to remove':'♡ Save this restaurant'}</button>`;const sticky=inCart?`<button class="sticky-cart-bar" id="view-cart-bar"><span>View cart · ${t.count} item${t.count>1?'s':''}</span><span>₩${t.itemsTotal.toLocaleString()} ↗</span></button>`:'';detailFlow(body,sticky);$$('#detail-body [data-menu-cat]').forEach(b=>b.onclick=()=>renderRestaurantMenu(p,menu,b.dataset.menuCat));$$('#detail-body [data-menu-item]').forEach(b=>b.onclick=()=>openMenuItem(p.id,b.dataset.menuItem));$('#place-save-detail').onclick=()=>{saved=saved.includes(p.id)?saved.filter(x=>x!==p.id):[...saved,p.id];put('saved',saved);renderRestaurantMenu(p,menu,activeCat)};$('#view-cart-bar')?.addEventListener('click',()=>openCart())}
function openRestaurant(id){const p=restaurants.find(x=>x.id===id);if(!p)return;const menu=menuData[id];if(!menu){detailFlow(`${window.RoomBapMedia.photo(p,'venue-detail-photo')}<h2 class="detail-title" id="detail-title">${escapeHTML(p.en)}</h2>${window.RoomBapMedia.credit(p.id)}<p class="detail-description">A delivery menu for this restaurant isn’t available yet.</p>`,'');return}renderRestaurantMenu(p,menu,menu.items[0].category)}
function dietaryChipsHTML(item){const d=window.RoomBapDietary;if(!d)return '';const chips=[];if(d.isVeganSuitable(item))chips.push('<span>Vegan verified</span>');if(d.isVegetarianSuitable(item))chips.push('<span>Vegetarian verified</span>');const halal=d.halalStatus(item);if(halal.label)chips.push(`<span>${escapeHTML(halal.label)}</span>`);return chips.length?`<div class="details-chips dietary-chips">${chips.join('')}</div>`:''}
function ingredientsNoteHTML(item){if(!item.ingredients||!item.ingredients.length)return '';return `<p class="gentle-note">Ingredients (dish-type reference, not restaurant-confirmed): ${item.ingredients.map(escapeHTML).join(', ')}. Dietary and allergen suitability have not been verified by the restaurant — confirm before ordering.</p>`}
function optionGroupHTML(g){const type=g.type==='single'?'radio':'checkbox';return `<div class="option-group"><div class="option-group-head"><strong>${escapeHTML(g.label)}</strong><span>${g.required?'Required':'Optional'}${g.type==='multi'&&g.max?` · up to ${g.max}`:''}</span></div>${g.options.map(o=>`<div class="option-row ${o.soldOut?'sold-out':''}"><input type="${type}" id="opt-${g.key}-${o.key}" name="group-${g.key}" data-group="${g.key}" value="${o.key}" ${o.soldOut?'disabled':''}><label for="opt-${g.key}-${o.key}"><span>${escapeHTML(o.label)}${o.soldOut?' (Sold out)':''}</span><span>${o.price?`+₩${o.price.toLocaleString()}`:''}</span></label></div>`).join('')}</div>`}
function selectionPrice(item,selections){let extra=0;item.groups.forEach(g=>{(selections[g.key]||[]).forEach(ok=>{const o=g.options.find(x=>x.key===ok);if(o)extra+=o.price})});return item.price+extra}
function selectionSummary(item,selections){const parts=[];item.groups.forEach(g=>{const chosen=selections[g.key]||[];if(!chosen.length)return;const labels=chosen.map(ok=>g.options.find(o=>o.key===ok)?.label).filter(Boolean);if(labels.length)parts.push(`${g.label}: ${labels.join(', ')}`)});return parts.join(' · ')}
function openMenuItem(restaurantId,itemId,initialSelections,initialQty){const p=restaurants.find(x=>x.id===restaurantId);const menu=menuData[restaurantId];const item=menu.items.find(i=>i.id===itemId);if(!item)return;let qty=initialQty||1;const selections={};item.groups.forEach(g=>{selections[g.key]=initialSelections&&initialSelections[g.key]?[...initialSelections[g.key]]:[]});const icon=placeCategoryInfo[item.category]?.icon||'🍽️';const body=`<div class="menu-item-hero menu-visual" data-cat="${escapeHTML(item.category)}" aria-hidden="true">${icon}</div><p class="detail-kicker">${escapeHTML(p.en)}</p><h2 class="detail-title" id="detail-title">${escapeHTML(item.name)}</h2><p class="detail-description">${escapeHTML(item.description)}</p>${dietaryChipsHTML(item)}${ingredientsNoteHTML(item)}${item.groups.map(optionGroupHTML).join('')}<div class="qty-stepper"><button id="item-qty-minus" aria-label="Decrease quantity">−</button><span id="item-qty">${qty}</span><button id="item-qty-plus" aria-label="Increase quantity">+</button></div><p id="option-missing-note" class="option-missing" hidden></p>`;detailFlow(body,'');item.groups.forEach(g=>{(selections[g.key]||[]).forEach(ok=>{const el=$('#opt-'+g.key+'-'+ok);if(el)el.checked=true})});const refreshSticky=()=>{const missing=item.groups.filter(g=>g.required&&(selections[g.key]||[]).length<g.min);const total=selectionPrice(item,selections)*qty;$('#detail-sticky').innerHTML=`<button class="primary" id="add-to-cart-btn" ${missing.length?'disabled':''}>Add · ₩${total.toLocaleString()}</button>`;$('#option-missing-note').hidden=missing.length===0;if(missing.length)$('#option-missing-note').textContent=`Select ${missing.map(g=>g.label).join(', ')} to continue.`;$('#add-to-cart-btn').onclick=()=>{if(missing.length)return;addToCart(restaurantId,itemId,selections,qty)}};item.groups.forEach(g=>{$$(`#detail-body [data-group="${g.key}"]`).forEach(inp=>inp.onchange=e=>{let checked=$$(`#detail-body [data-group="${g.key}"]:checked`).map(x=>x.value);if(g.type==='multi'&&g.max&&checked.length>g.max){e.target.checked=false;checked=$$(`#detail-body [data-group="${g.key}"]:checked`).map(x=>x.value)}selections[g.key]=checked;refreshSticky()})});$('#item-qty-minus').onclick=()=>{qty=Math.max(1,qty-1);$('#item-qty').textContent=qty;refreshSticky()};$('#item-qty-plus').onclick=()=>{qty=Math.min(10,qty+1);$('#item-qty').textContent=qty;refreshSticky()};refreshSticky()}
function cartLineKey(itemId,selections){return itemId+'::'+Object.keys(selections).sort().map(k=>k+'='+[...(selections[k]||[])].sort().join(',')).join('|')}
function addToCart(restaurantId,itemId,selections,qty){const doAdd=()=>{const menu=menuData[restaurantId];const item=menu.items.find(i=>i.id===itemId);const unitPrice=selectionPrice(item,selections);const key=cartLineKey(itemId,selections);const existing=cart.items.find(l=>l.key===key);if(existing){existing.qty=Math.min(10,existing.qty+qty)}else{cart.items.push({lineId:'cl'+Date.now()+Math.random().toString(36).slice(2,7),key,restaurantId,itemId,name:item.name,category:item.category,selections,unitPrice,qty})}cart.restaurantId=restaurantId;put('cart',cart);renderCartBadge();toast('Added to your cart.');openCart()};if(cart.restaurantId&&cart.restaurantId!==restaurantId&&cart.items.length){promptReplaceCart(restaurantId,()=>{cart={restaurantId:null,items:[]};doAdd()});return}doAdd()}
function promptReplaceCart(newRestaurantId,onReplace){const current=restaurants.find(x=>x.id===cart.restaurantId);const next=restaurants.find(x=>x.id===newRestaurantId);detailFlow(`<h2 class="detail-title" id="detail-title">Start a new cart?</h2><p class="detail-description">Your cart has items from ${escapeHTML(current?.en||'another restaurant')}. RoomBap supports ordering from one restaurant at a time.</p><p class="detail-description">Switching to ${escapeHTML(next?.en||'this restaurant')} will clear your current cart.</p><div class="replace-cart-actions"><button class="back-button" id="keep-cart-btn">Keep current cart</button><button class="primary" id="replace-cart-btn">Replace cart</button></div>`,'');$('#keep-cart-btn').onclick=()=>openRestaurant(cart.restaurantId);$('#replace-cart-btn').onclick=()=>onReplace()}
function cartTotals(){const menu=cart.restaurantId?menuData[cart.restaurantId]:null;const itemsTotal=cart.items.reduce((s,l)=>s+l.unitPrice*l.qty,0);const deliveryFee=menu?menu.deliveryFee:0;const minOrder=menu?menu.minOrder:0;const count=cart.items.reduce((s,l)=>s+l.qty,0);return {itemsTotal,deliveryFee,total:itemsTotal+deliveryFee,minOrder,count,belowMin:itemsTotal<minOrder}}
function renderCartBadge(){const t=cartTotals();$('#basket-count').hidden=t.count===0;$('#basket-count').textContent=t.count}
function cartLineHTML(l){const icon=placeCategoryInfo[l.category]?.icon||'🍽️';const item=menuData[l.restaurantId]?.items.find(i=>i.id===l.itemId);const summary=item?selectionSummary(item,l.selections):'';return `<div class="cart-item"><span class="cart-item-photo menu-visual" data-cat="${escapeHTML(l.category)}" aria-hidden="true">${icon}</span><div class="cart-item-info"><h4>${escapeHTML(l.name)}</h4>${summary?`<p class="cart-item-options">${escapeHTML(summary)}</p>`:''}<div class="cart-item-row"><div class="cart-item-qty"><button data-qty-minus="${l.lineId}" aria-label="Decrease quantity">−</button><span>${l.qty}</span><button data-qty-plus="${l.lineId}" aria-label="Increase quantity">+</button></div><strong>₩${(l.unitPrice*l.qty).toLocaleString()}</strong></div><div class="cart-item-actions"><button data-edit-line="${l.lineId}">Edit options</button><button data-remove-line="${l.lineId}">Remove</button></div></div></div>`}
function openCart(){if(!cart.restaurantId||!cart.items.length){detailFlow(`<h2 class="detail-title" id="detail-title">Your cart is empty.</h2><p class="detail-description">Choose a restaurant to start an order.</p><button class="primary full-button" id="browse-food-btn">Explore restaurants ↗</button>`,'');$('#browse-food-btn').onclick=()=>{closeDetail();$('#browse-section').scrollIntoView({behavior:'smooth',block:'start'})};return}const p=restaurants.find(x=>x.id===cart.restaurantId);const t=cartTotals();const body=`<p class="detail-kicker">YOUR CART</p><h2 class="detail-title" id="detail-title">${escapeHTML(p.en)}</h2>${cart.items.map(cartLineHTML).join('')}<button class="cart-add-more" id="add-more-btn">+ Add more items</button>${t.belowMin?`<p class="min-order-note">Add ₩${(t.minOrder-t.itemsTotal).toLocaleString()} more to reach the minimum order.</p>`:''}<div class="detail-line"><span>Items</span><strong>₩${t.itemsTotal.toLocaleString()}</strong></div><div class="detail-line"><span>Delivery fee</span><strong>₩${t.deliveryFee.toLocaleString()}</strong></div><div class="detail-line"><strong>Total</strong><strong>₩${t.total.toLocaleString()}</strong></div><p class="gentle-note">Delivery fee and minimum order are demo values for this prototype, not confirmed restaurant figures.</p>`;const sticky=`<button class="primary" id="go-checkout-btn" ${t.belowMin?'disabled':''}>${t.belowMin?'Minimum order not reached':`Proceed to checkout · ₩${t.total.toLocaleString()}`}</button>`;detailFlow(body,sticky);$('#add-more-btn').onclick=()=>openRestaurant(cart.restaurantId);$$('[data-qty-minus]').forEach(b=>b.onclick=()=>updateCartQty(b.dataset.qtyMinus,-1));$$('[data-qty-plus]').forEach(b=>b.onclick=()=>updateCartQty(b.dataset.qtyPlus,1));$$('[data-remove-line]').forEach(b=>b.onclick=()=>removeCartLine(b.dataset.removeLine));$$('[data-edit-line]').forEach(b=>b.onclick=()=>editCartLine(b.dataset.editLine));$('#go-checkout-btn')?.addEventListener('click',()=>{if(!t.belowMin)openCheckout()})}
function updateCartQty(lineId,delta){const line=cart.items.find(l=>l.lineId===lineId);if(!line)return;line.qty=Math.max(1,Math.min(10,line.qty+delta));put('cart',cart);renderCartBadge();openCart()}
function removeCartLine(lineId){cart.items=cart.items.filter(l=>l.lineId!==lineId);if(!cart.items.length)cart.restaurantId=null;put('cart',cart);renderCartBadge();openCart()}
function editCartLine(lineId){const line=cart.items.find(l=>l.lineId===lineId);if(!line)return;cart.items=cart.items.filter(l=>l.lineId!==lineId);if(!cart.items.length)cart.restaurantId=null;put('cart',cart);openMenuItem(line.restaurantId,line.itemId,line.selections,line.qty)}
const countryCodes=['+82','+1','+44','+81','+86','+65','+66','+84','+60','+61'];
let checkoutInfo=null;
function openCheckout(){if(!cart.restaurantId||!cart.items.length)return openCart();const t=cartTotals();if(t.belowMin)return openCart();const p=restaurants.find(x=>x.id===cart.restaurantId);const body=`<p class="detail-kicker">ORDER DETAILS</p><h2 class="detail-title" id="detail-title">${escapeHTML(p.en)}</h2><button class="text-button" id="edit-cart-link">${t.count} item${t.count>1?'s':''} · ₩${t.itemsTotal.toLocaleString()} · Edit ↗</button><div class="checkout-section"><h3>Receiving at your stay</h3><div class="form-row"><label>Hotel</label><input value="${escapeHTML(hotelStay.hotelName)}" disabled></div><div class="form-row"><label>Address</label><input value="${escapeHTML(hotelStay.addressEn)}" disabled></div><div class="form-row"><label for="room-number">Room number</label><input id="room-number" value="${escapeHTML(hotelStay.room)}"></div><div class="form-row"><label for="pickup-location">Receiving location</label><select id="pickup-location">${hotelStay.pickupOptions.map(o=>`<option value="${o.id}">${escapeHTML(o.label)}</option>`).join('')}</select><p class="pickup-note">${hotelStay.pickupOptions.length===1?'This stay only supports '+hotelStay.pickupOptions[0].label.toLowerCase()+'.':'Only locations allowed by this stay are listed.'}</p></div></div><div class="checkout-section"><h3>Your details</h3><div class="form-row"><label for="guest-name">Name</label><input id="guest-name" placeholder="Full name"><p class="field-error" id="name-error" hidden>Enter your name.</p></div><div class="form-row"><label for="guest-phone">Contact number</label><div class="phone-row"><select id="guest-phone-code">${countryCodes.map(c=>`<option ${c==='+82'?'selected':''}>${c}</option>`).join('')}</select><input id="guest-phone" placeholder="Phone number"></div><p class="field-error" id="phone-error" hidden>Enter a contact number.</p></div></div><div class="checkout-section"><h3>Requests</h3><div class="form-row"><label for="restaurant-note">Note to the restaurant</label><textarea id="restaurant-note" placeholder="e.g. less spicy, no onions"></textarea></div><div class="form-row"><label for="receiving-note">Note for receiving</label><textarea id="receiving-note" placeholder="e.g. call on arrival"></textarea></div><div class="form-row"><label style="display:flex;align-items:center"><input type="checkbox" id="need-cutlery" checked style="width:18px;height:18px;margin-right:8px">Send disposable cutlery</label></div></div>`;const sticky=`<button class="primary" id="go-payment-btn">Continue to payment ↗</button>`;detailFlow(body,sticky);$('#edit-cart-link').onclick=()=>openCart();$('#go-payment-btn').onclick=()=>{let ok=true;if(!$('#guest-name').value.trim()){$('#name-error').hidden=false;ok=false}else $('#name-error').hidden=true;if(!$('#guest-phone').value.trim()){$('#phone-error').hidden=false;ok=false}else $('#phone-error').hidden=true;if(!ok){($('#guest-name').value.trim()?$('#guest-phone'):$('#guest-name')).focus();return}checkoutInfo={room:$('#room-number').value.trim()||hotelStay.room,pickup:hotelStay.pickupOptions.find(o=>o.id===$('#pickup-location').value)||hotelStay.pickupOptions[0],name:$('#guest-name').value.trim(),phoneCode:$('#guest-phone-code').value,phone:$('#guest-phone').value.trim(),restaurantNote:$('#restaurant-note').value.trim(),receivingNote:$('#receiving-note').value.trim(),cutlery:$('#need-cutlery').checked};openPayment()}}
const paymentMethods=[{id:'demo-visa',label:'Demo Visa •••• 4242'},{id:'demo-master',label:'Demo Mastercard •••• 4444'},{id:'demo-stay',label:'Charge to room (demo)'}];
let selectedPayment=paymentMethods[0].id;
function openPayment(){if(!checkoutInfo)return openCheckout();const p=restaurants.find(x=>x.id===cart.restaurantId);const t=cartTotals();const body=`<p class="detail-kicker">PAYMENT</p><h2 class="detail-title" id="detail-title">Review & pay</h2><div class="checkout-section"><h3>${escapeHTML(p.en)}</h3>${cart.items.map(l=>`<div class="detail-line"><span>${escapeHTML(l.name)} × ${l.qty}</span><strong>₩${(l.unitPrice*l.qty).toLocaleString()}</strong></div>`).join('')}</div><div class="checkout-section"><h3>Receiving</h3><p class="detail-description">${escapeHTML(hotelStay.hotelName)} · Room ${escapeHTML(checkoutInfo.room)}<br>${escapeHTML(checkoutInfo.pickup.label)}<br>${escapeHTML(checkoutInfo.name)} · ${escapeHTML(checkoutInfo.phoneCode)} ${escapeHTML(checkoutInfo.phone)}</p></div><div class="checkout-section"><h3>Payment method</h3>${paymentMethods.map(m=>`<label class="pay-method"><input type="radio" name="pay" value="${m.id}" ${m.id===selectedPayment?'checked':''}><span>${escapeHTML(m.label)}</span></label>`).join('')}<p class="demo-checkout-banner">Demo checkout — no charge</p></div><div class="checkout-section"><h3>Amount</h3><div class="detail-line"><span>Items</span><strong>₩${t.itemsTotal.toLocaleString()}</strong></div><div class="detail-line"><span>Delivery fee</span><strong>₩${t.deliveryFee.toLocaleString()}</strong></div><div class="detail-line"><strong>Total</strong><strong>₩${t.total.toLocaleString()}</strong></div></div>`;const sticky=`<button class="primary" id="pay-btn">Demo checkout · ₩${t.total.toLocaleString()} · no charge</button>`;detailFlow(body,sticky);$$('input[name="pay"]').forEach(r=>r.onchange=()=>{selectedPayment=r.value});$('#pay-btn').onclick=completeOrder}
function completeOrder(){if(orderSubmitting)return;orderSubmitting=true;const btn=$('#pay-btn');if(btn){btn.disabled=true;btn.textContent='Placing demo order…'}const p=restaurants.find(x=>x.id===cart.restaurantId);const t=cartTotals();const order={id:'RB-'+String(Date.now()).slice(-6),restaurantId:cart.restaurantId,restaurantName:p.en,items:cart.items.map(l=>{const item=menuData[l.restaurantId].items.find(i=>i.id===l.itemId);return {name:l.name,qty:l.qty,unitPrice:l.unitPrice,options:item?selectionSummary(item,l.selections):''}}),itemsTotal:t.itemsTotal,deliveryFee:t.deliveryFee,total:t.total,room:checkoutInfo.room,pickup:checkoutInfo.pickup.label,name:checkoutInfo.name,phone:checkoutInfo.phoneCode+' '+checkoutInfo.phone,restaurantNote:checkoutInfo.restaurantNote,receivingNote:checkoutInfo.receivingNote,cutlery:checkoutInfo.cutlery,payment:(paymentMethods.find(m=>m.id===selectedPayment)||{}).label,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}),stage:0};orders.unshift(order);put('orders',orders);cart={restaurantId:null,items:[]};put('cart',cart);renderCartBadge();checkoutInfo=null;orderSubmitting=false;showOrder(order)}
// This is category-based browsing personalization, separate from item-level dietary verification.
function forYouCategory(diet){return diet==='halal'?'Halal':['vegan','vegetarian'].includes(diet)?'Salad':null}
function filterBrowsePlaces(places,collection,selectedCategory,diet){
 const requiredCategory=collection==='For you'?forYouCategory(diet):null;
 return places.filter(p=>{const categories=p.categories||[p.category];return (!requiredCategory||categories.includes(requiredCategory))&&(selectedCategory==='All'||categories.includes(selectedCategory))});
}
function renderFoods(){
 const isMap=tab==='Seoul Map',isStar=tab==='Star’s Pick';
 $('#seoul-map-panel').hidden=!isMap;$('#star-pick-panel').hidden=!isStar;
 $('#story-section').hidden=isStar;$('#food-list').hidden=isMap||isStar;
 $('#browse-section>.section-heading').hidden=isMap||isStar;
 if($('#catalog-note'))$('#catalog-note').hidden=isMap||isStar;
 if(isMap){window.RoomBapTrail.show();return}
 if(isStar){renderStarPick();return}
 const preferredCategory=tab==='For you'?forYouCategory(profile.diet):null;
 let list=filterBrowsePlaces(restaurants,tab,category,profile.diet);
 if(tab==='Hotel’s Pick')list=[];
 $('#collection-title').textContent=tab==='Hotel’s Pick'?'Your stay’s recommendations':category!=='All'?category+' near Hongdae':preferredCategory?preferredCategory+' for you':'Real places around Hongdae';
 $('#collection-count').textContent=`${list.length} places`;
 $('#collection-kicker').textContent=preferredCategory?'PICKED FOR YOUR EATING STYLE':'LOCAL PICKS · UPDATED 2026.10.29';
 let note=$('#catalog-note');if(!note){note=document.createElement('p');note.id='catalog-note';note.className='catalog-note';$('#food-list').before(note)}
 const noteCategory=preferredCategory||category;
 note.textContent=noteCategory==='Halal'?'Halal and Muslim-friendly options around Hongdae, Hapjeong and nearby Sinchon. Certification is not verified; check the dish with the restaurant.':noteCategory==='Salad'?'Salads, poke and plant-based options around Hongdae, Yeonnam and Sangsu. Check the menu for vegan options and dressing ingredients.':'Source-researched places to explore. Check current menus and delivery coverage; RoomBap ordering is a demo.';
 if(preferredCategory){const dietLabel={halal:'Halal',vegan:'Vegan',vegetarian:'Vegetarian'}[profile.diet];note.textContent=`Your ${dietLabel} preference · showing ${preferredCategory} places only. `+note.textContent}
 $('#food-list').innerHTML=list.map(restaurantCard).join('')||(tab==='Hotel’s Pick'?'<div class="empty">Hotel-endorsed places are not confirmed yet. Explore the researched places in For you.<button class="text-button" id="explore-all-places">Explore all restaurants ↗</button></div>':preferredCategory?`<div class="empty">No ${escapeHTML(category)} places match your ${escapeHTML(profile.diet)} preference.<button class="text-button" id="show-preference-places">Show ${escapeHTML(preferredCategory)} places ↗</button><button class="text-button" id="edit-food-filter">Edit food preferences</button></div>`:'<div class="empty">No places match this category yet.</div>');
 bindCards($('#food-list'));
 const resetBrowseCategory=()=>{category='All';$$('[data-category]').forEach(b=>b.classList.remove('active'));renderFoods()};
 $('#show-preference-places')?.addEventListener('click',resetBrowseCategory);
 $('#edit-food-filter')?.addEventListener('click',()=>openSurvey(1));
 $('#explore-all-places')?.addEventListener('click',()=>{tab='For you';$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});resetBrowseCategory()});
}

$$('[data-category]').forEach(b=>b.onclick=()=>{if(tab==='Seoul Map'||tab==='Star’s Pick'){tab='For you';$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x.dataset.tab===tab);x.setAttribute('aria-selected',x.dataset.tab===tab)})}category=category===b.dataset.category?'All':b.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));renderFoods()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b)});renderFoods()});
const promos=[{kicker:'A GOOD PLACE TO START',title:'Your first Korean meal?',description:'Find a meal you’ll love.',button:'Explore food ↗',photo:'chicken',action:()=>$('#browse-section').scrollIntoView({behavior:'smooth',block:'start'})},{kicker:'A BITE OF THE STORY',title:'Tonight feels like a K-drama.',description:'A crispy chicken night, right at your stay.',button:'See the story ↗',photo:'chicken',action:()=>$('#drama-story').click()},{kicker:'COMFORT FOOD, CLOSE BY',title:'A warm bowl. A happy night.',description:'Meet kalguksu, your next comfort food.',button:'Explore noodles ↗',photo:'noodles',action:()=>{tab='For you';category='Noodles';$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x.dataset.tab===tab);x.setAttribute('aria-selected',x.dataset.tab===tab)});$$('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));renderFoods();$('#browse-section').scrollIntoView({behavior:'smooth',block:'start'})}}];
let promoIndex=0;function setPromo(i){promoIndex=i;const p=promos[i];$('#promo-kicker').textContent=p.kicker;$('#promo-title').textContent=p.title;if(i===0)$('#promo-title').innerHTML='Your first<br>Korean meal?';$('#promo-description').textContent=p.description;$('#promo-action').textContent=p.button;$('.promo-image').className='promo-image food-photo photo-'+p.photo;$$('[data-promo]').forEach(x=>{x.classList.toggle('active',Number(x.dataset.promo)===i);x.setAttribute('aria-pressed',Number(x.dataset.promo)===i)})}$$('[data-promo]').forEach(x=>x.onclick=()=>setPromo(Number(x.dataset.promo)));$('#promo-action').onclick=()=>promos[promoIndex].action();
function detail(html){$('#detail-body').innerHTML=html;if(!$('#detail').open){lastFocus=document.activeElement;$('#detail').showModal()}$('#detail').scrollTop=0;$('#detail-close').focus()}
function closeDetail(){$('#detail').classList.remove('order-flow');$('#detail-sticky').innerHTML='';$('#detail').close();lastFocus?.focus()}$('#detail-close').onclick=closeDetail;$('#detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail()});
$('#basket').onclick=()=>openCart();
function showOrder(o){$('#detail').classList.remove('order-flow');$('#detail-sticky').innerHTML='';detail(`<div class="order-check">✓</div><p class="detail-kicker">DEMO ORDER CREATED · ${o.id}</p><h2 class="detail-title" id="detail-title">${['Your demo order is accepted.','Your demo meal is being prepared.','Your demo meal is on its way.','Your demo meal has arrived.'][o.stage]}</h2><div class="checkout-section"><h3>${escapeHTML(o.restaurantName)}</h3>${o.items.map(it=>`<div class="detail-line"><span>${escapeHTML(it.name)} × ${it.qty}${it.options?`<br><small>${escapeHTML(it.options)}</small>`:''}</span><strong>₩${(it.unitPrice*it.qty).toLocaleString()}</strong></div>`).join('')}<div class="detail-line"><span>Delivery fee</span><strong>₩${o.deliveryFee.toLocaleString()}</strong></div><div class="detail-line"><strong>Total</strong><strong>₩${o.total.toLocaleString()}</strong></div></div><p class="detail-description">${escapeHTML(hotelStay.hotelName)} · Room ${escapeHTML(o.room)} · ${escapeHTML(o.pickup)}<br>${escapeHTML(o.name)} · ${escapeHTML(o.phone)}${o.restaurantNote?`<br>Restaurant note: ${escapeHTML(o.restaurantNote)}`:''}${o.receivingNote?`<br>Receiving note: ${escapeHTML(o.receivingNote)}`:''}<br>${o.cutlery?'Cutlery requested':'No cutlery requested'}</p><p class="gentle-note">This demo order was not sent to the real restaurant and no payment was charged.</p><div class="order-steps">${['Accepted','Preparing','Out for delivery','Arrived'].map((x,i)=>`<span class="${i<=o.stage?'done':''}">${i<=o.stage?'●':'○'} &nbsp; ${x}</span>`).join('')}</div><button class="primary full-button" id="advance-order" ${o.stage===3?'disabled':''}>${o.stage===3?'Demo complete':'Preview next status ↗'}</button>`);$('#advance-order').onclick=()=>{o.stage=Math.min(3,o.stage+1);put('orders',orders);showOrder(o)}}
$('#drama-story').onclick=()=>openStarDetail('my-love-chimaek');
$('#artist-story').onclick=()=>{$('[data-tab="Seoul Map"]').click();$('#browse-section').scrollIntoView({behavior:'smooth',block:'start'})};
$$('[data-nav]').forEach(b=>b.onclick=()=>{const n=b.dataset.nav;if(n==='home'){window.scrollTo({top:0,behavior:'smooth'});return}if(n==='saved'){detail(`<h2 class="detail-title" id="detail-title">Saved for later ♡</h2><div class="food-grid">${restaurants.filter(p=>saved.includes(p.id)).map(restaurantCard).join('')||'<p class="detail-description">Tap a heart on a restaurant to save it here.</p>'}</div>`);bindCards($('#detail-body'))}if(n==='orders'){detail(`<h2 class="detail-title" id="detail-title">Your demo orders</h2>${orders.map(o=>`<button class="detail-line" style="width:100%;text-align:left" data-order="${o.id}"><span>${escapeHTML(o.restaurantName)}<small style="display:block;margin-top:5px">${o.id} · ${o.time}</small></span><strong>₩${o.total.toLocaleString()} ↗</strong></button>`).join('')||'<p class="detail-description">Your demo orders will appear here.</p>'}`);$$('[data-order]').forEach(x=>x.onclick=()=>showOrder(orders.find(o=>o.id===x.dataset.order)))}if(n==='help'){detail('<p class="detail-kicker">A LITTLE HELP</p><h2 class="detail-title" id="detail-title">Make yourself at home.</h2><p class="field-label">Do I need a Korean phone number?</p><p class="detail-description">No. This demo starts with your stay already selected.</p><p class="field-label">Can I change my food preferences?</p><p class="detail-description">Yes. Use the settings button at the top. You can close any survey step with ×.</p><p class="field-label">Is this a real order?</p><p class="detail-description">This is an interactive prototype. No payment, food delivery, or live AI support is connected.</p><p class="field-label">What about allergies?</p><p class="detail-description">Sample ingredient labels cannot establish that food is safe for you. Confirm ingredients and preparation with the restaurant before a real purchase.</p>')}});
$$('a[href="#home"]').forEach(x=>x.onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'})});
applyProfile();
renderCartBadge();
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});['.categories','#browse-section','.story-section','.how'].forEach(selector=>{const el=$(selector);el.classList.add('reveal');observer.observe(el)})}
let seen=false;try{seen=!!sessionStorage.getItem('roombap-intro-seen')}catch{}if(!seen)openSurvey();

const contentItems=window.RoomBapContent||[];let contentFilter='All',contentListFocus=null,contentView='browse';
function magPhoto(ref,sizeClass){if(ref.src){return {html:`<span class="venue-photo ${escapeHTML(sizeClass)}"><img data-venue-photo src="${escapeHTML(ref.src)}" alt="${escapeHTML(ref.alt||'Food photograph')}" loading="lazy" decoding="async" width="800" height="600"></span>`,credit:`<p class="source-caption venue-photo-credit">${escapeHTML(ref.credit||'Food photograph')} · <a href="${escapeHTML(ref.sourceUrl)}" target="_blank" rel="noopener noreferrer">Photo source ↗</a></p>`}}const p=restaurants.find(x=>x.id===ref.restaurantId);const photoHtml=p?window.RoomBapMedia.photo(p,sizeClass):'<span class="venue-photo-fallback" aria-hidden="true">Photo unavailable</span>';const badge=ref.placeholder?'<span class="mag-photo-badge">Placeholder photo</span>':'';const credit=p?window.RoomBapMedia.credit(p.id):'';return {html:photoHtml+badge,credit}}
function contentCard(c){const thumb=magPhoto(c.hero,'content-card-photo-img');return `<button type="button" class="content-card" data-content="${c.id}"><span class="content-card-photo">${thumb.html}</span><span class="content-card-body"><span class="content-card-category">${escapeHTML(c.category)}</span><span class="content-card-title">${escapeHTML(c.title)}</span><span class="content-card-desc">${escapeHTML(c.cardDescription)}</span></span></button>`}
function renderContentList(){const list=contentItems.filter(c=>contentFilter==='All'||c.category===contentFilter);$('#content-card-list').innerHTML=list.map(contentCard).join('')||'<div class="empty">No stories in this category yet.</div>';$$('#content-card-list [data-content]').forEach(b=>b.onclick=()=>openContentDetail(b.dataset.content))}
function showContentBrowse(){contentView='browse';$('#content-list-detail').hidden=true;$('#content-list-browse').hidden=false}
function showContentDetailView(){contentView='detail';$('#content-list-browse').hidden=true;$('#content-list-detail').hidden=false;$('#content-list-detail').scrollTop=0}
function openContentList(){contentListFocus=document.activeElement;contentFilter='All';showContentBrowse();$$('#content-list [data-content-filter]').forEach(b=>{const active=b.dataset.contentFilter==='All';b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderContentList();$('#content-list').showModal();$('#content-list-back').focus()}
function closeContentList(){if($('#content-list').open)$('#content-list').close();(contentListFocus||$('#culture-entry')).focus();contentListFocus=null}
$('#culture-entry').onclick=openContentList;
$('#content-list-back').onclick=()=>{if(contentView==='detail')showContentBrowse();else closeContentList()};
$('#content-list').addEventListener('cancel',e=>{e.preventDefault();closeContentList()});
$$('#content-list [data-content-filter]').forEach(b=>b.onclick=()=>{contentFilter=b.dataset.contentFilter;$$('#content-list [data-content-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderContentList()});
function exploreRelatedCategory(cat){closeContentList();tab='For you';category=cat;$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x.dataset.tab===tab);x.setAttribute('aria-selected',x.dataset.tab===tab)});$$('[data-category]').forEach(x=>x.classList.toggle('active',x.dataset.category===category));renderFoods();$('#browse-section').scrollIntoView({behavior:'smooth',block:'start'})}
function openContentDetail(id){
 const c=contentItems.find(x=>x.id===id);if(!c)return;
 const hero=magPhoto(c.hero,'mag-photo-fill');
 const secs=c.sections.map(s=>{const m=(s.src||s.restaurantId)?magPhoto(s,'mag-photo-fill'):null;return `<div class="mag-block">${m?`<div class="mag-photo">${m.html}</div>${m.credit}`:''}<h3 class="mag-subhead">${escapeHTML(s.subhead)}</h3><p class="mag-text">${escapeHTML(s.text)}</p></div>`}).join('');
 const related=(c.relatedRestaurantIds||[]).map(id=>restaurants.find(p=>p.id===id)).filter(Boolean).map(p=>`<button class="trend-venue-link" data-trend-venue="${escapeHTML(p.id)}">${window.RoomBapMedia.photo(p,'trend-venue-photo')}<span><strong>${escapeHTML(p.en)}</strong><small>Listed menu · check stock and delivery</small></span><b>↗</b></button>`).join('');
 const external=c.externalLink?`<a class="text-button trend-source-link" href="${escapeHTML(c.externalLink.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(c.externalLink.label)}</a>`:'';
 const sources=[...(c.source?[{url:c.source,label:c.sourceLabel||'Source'}]:[]),...(c.extraSources||[])].map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.label)} ↗</a>`).join('<br>');
 $('#content-list-detail').innerHTML=`<div class="mag-block mag-hero"><div class="mag-photo">${hero.html}</div>${hero.credit}<h2 class="mag-title">${escapeHTML(c.title)}</h2><p class="mag-intro">${escapeHTML(c.hero.text)}</p></div>${secs}${related}${c.availabilityNote?`<p class="gentle-note trend-availability">${escapeHTML(c.availabilityNote)}</p>`:''}${external}<button class="primary full-button" id="content-explore-related">${escapeHTML(c.ctaLabel||`Explore ${c.relatedCategory} ↗`)}</button><p class="source-caption mag-sources">${sources||'RoomBap editorial note'}<br>Checked ${escapeHTML(c.addedAt)}</p>`;
 $('#content-explore-related').onclick=()=>exploreRelatedCategory(c.relatedCategory);
 $$('#content-list-detail [data-trend-venue]').forEach(b=>b.onclick=()=>{const id=b.dataset.trendVenue;closeContentList();openRestaurant(id)});
 showContentDetailView();
}

const starItems=window.RoomBapStarContent||[],starMatches=window.RoomBapStarContentMatches||{};let starFilter='All';
const relationLabel={featured:'Featured restaurant',same_brand:'Same brand','same-brand':'Same brand','try-this':'Try this dish'};
function starPhoto(c,kind,style='',eager=false){const scene=kind==='scene';const src=scene?c.sceneImage:c.foodImage;const alt=scene?c.sceneAlt:c.foodAlt;const position=scene?c.scenePosition:'50% 50%';return `<span class="star-media ${style}"><span class="star-media-unavailable">${scene?'Scene':'Food photo'} unavailable</span>${src?`<img data-star-photo src="${escapeHTML(src)}" alt="${escapeHTML(alt||c.food)}" style="object-position:${escapeHTML(position||'50% 50%')}" loading="${eager?'eager':'lazy'}" decoding="async">`:''}</span>`}
document.addEventListener('error',e=>{if(e.target.matches?.('img[data-star-photo]')){e.target.hidden=true;e.target.closest('.star-media')?.classList.add('photo-unavailable')}},true);
function starCard(c){return `<button type="button" class="star-card" data-star="${escapeHTML(c.id)}"><span class="star-card-visual">${starPhoto(c,'scene','star-card-scene')}<span class="star-tag">${escapeHTML(c.category)}</span></span><span class="star-card-body"><h3>${escapeHTML(c.work)}</h3><p>${escapeHTML(c.food)}</p><span class="star-card-footer"><span>From the scene to your plate</span><span class="star-card-cta">Explore the story <span aria-hidden="true">↗</span></span></span></span></button>`}
function renderStarPick(){const list=starItems.filter(c=>starFilter==='All'||c.category===starFilter);$('#star-pick-list').innerHTML=list.map(starCard).join('')||'<div class="empty">No stories in this category yet.</div>';$$('#star-pick-list [data-star]').forEach(b=>b.onclick=()=>openStarDetail(b.dataset.star))}
$$('#star-pick-panel [data-star-filter]').forEach(b=>b.onclick=()=>{starFilter=b.dataset.starFilter;$$('#star-pick-panel [data-star-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderStarPick()});
function starMatchCard(m){const p=restaurants.find(x=>x.id===m.restaurantId);if(!p)return'';const label=relationLabel[m.relation]||m.relation;const delivery={listed:'Delivery listed on Google Maps · coverage not confirmed',unknown:'Delivery not confirmed in the map listing'}[p.deliveryListing]||'Delivery not listed on Google Maps';return `<div class="star-match-card">${window.RoomBapMedia.photo(p,'star-match-photo')}<span class="star-match-info"><span class="star-match-relation">${escapeHTML(label)}</span><strong>${escapeHTML(p.en)}</strong><small>${escapeHTML(m.menu)} · ${p.priceRange?escapeHTML(p.priceRange):'See map for prices'}</small><small>${delivery}</small></span><button class="star-match-view" data-view-restaurant="${p.id}">View restaurant ↗</button></div>${window.RoomBapMedia.credit(p.id)}`}
function starDeliveryCard(c,r){return `<a class="star-delivery-card" href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer" aria-label="View ${escapeHTML(r.name)} delivery menu on Shuttle">${starPhoto(c,'food','star-delivery-photo')}<span class="star-delivery-info"><span class="star-match-relation">${escapeHTML(relationLabel[r.relation]||'Try this dish')}</span><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(r.menu)}</small><span class="star-delivery-cta">View delivery menu ↗</span></span></a>`}
function openStarDetail(id){
 const c=starItems.find(x=>x.id===id);if(!c)return;
 const matches=(starMatches[c.id]||[]).filter(m=>restaurants.some(p=>p.id===m.restaurantId));
 const refs=window.RoomBapStarDeliveryReferences?.[c.id]||[];
 $('#detail').classList.remove('order-flow');$('#detail-sticky').innerHTML='';
 detail(`<article class="star-detail"><div class="star-detail-hero">${starPhoto(c,'scene','star-detail-scene',true)}<span class="star-tag">${escapeHTML(c.category)}</span></div><p class="star-image-credit"><a href="${escapeHTML(c.sceneSource)}" target="_blank" rel="noopener noreferrer">Scene · ${escapeHTML(c.sceneCredit)} ↗</a></p><p class="eyebrow">THE SCENE YOU KNOW</p><h2 class="detail-title" id="detail-title">${escapeHTML(c.work)}</h2><p class="star-detail-story">${escapeHTML(c.story)}</p><section class="star-food-section" aria-labelledby="star-food-title">${starPhoto(c,'food','star-food-photo',true)}<p class="star-image-credit"><a href="${escapeHTML(c.foodSource)}" target="_blank" rel="noopener noreferrer">Food photo · ${escapeHTML(c.foodCredit)} ↗</a></p><p class="eyebrow">NOW, TAKE A BITE</p><h3 id="star-food-title">${escapeHTML(c.food)}</h3><p class="star-detail-story">${escapeHTML(c.whatToExpect)}</p><div class="details-chips">${(c.tags||[]).map(t=>`<span>${escapeHTML(t)}</span>`).join('')}</div></section><section class="star-restaurants" aria-labelledby="star-restaurants-title"><p class="eyebrow">FOLLOW YOUR CRAVING</p><h3 id="star-restaurants-title">Where to try it</h3>${refs.length?`<div class="star-delivery-list">${refs.map(r=>starDeliveryCard(c,r)).join('')}</div><p class="star-delivery-note">Menus open on Shuttle. Check delivery to your stay there. A dish match does not mean the restaurant appeared on screen.</p>`:''}${matches.length?`<h4 class="star-nearby-title">Also explore around Hongdae</h4><div class="star-match-list">${matches.map(starMatchCard).join('')}</div>`:''}${!refs.length&&!matches.length?'<p class="star-no-match">Restaurant matching coming soon.</p>':''}</section><button type="button" class="star-back-button" id="star-detail-back">← Back to Star’s Pick</button><details class="star-sources"><summary>Story sources & photo credits</summary>${c.sources.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.label)} ↗</a>`).join('')}<p>Scene and food photographs are credited separately above.</p></details></article>`);
 $('#star-detail-back').onclick=closeDetail;
 $$('#detail-body [data-view-restaurant]').forEach(b=>b.onclick=()=>{openRestaurant(b.dataset.viewRestaurant);$('#detail-body').insertAdjacentHTML('afterbegin','<button type="button" class="star-back-button star-restaurant-back" id="star-restaurant-back">← Back to the food story</button>');$('#star-restaurant-back').onclick=()=>openStarDetail(id)});
}
